INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35945, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物理的または時間的に間隔が大きく離れているさま。", "primary_collocate": null, "pronunciation": "とおい", "ipa": "toːi", "syllable_count": 3, "sentences": [{"text": "その島は本土から遠い。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "しま ほんど とお", "sentence_source": "generated"}, {"text": "遠い未来のことはわからない。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "とお みらい", "sentence_source": "generated"}, {"text": "星までの距離はとても遠い。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "ほし きょり とお", "sentence_source": "generated"}, {"text": "会社が遠いと毎朝大変だ。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "かいしゃ とお まいあさ たいへん", "sentence_source": "generated"}, {"text": "遠い外国から手紙が来た。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "とお がいこく てがみ き", "sentence_source": "generated"}, {"text": "ゴールはまだ遠い。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "とお", "sentence_source": "generated"}, {"text": "遠い記憶がふと戻った。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "とお きおく もど", "sentence_source": "generated"}, {"text": "一番遠い席に座った。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "いちばん とお せき すわ", "sentence_source": "generated"}, {"text": "試合の日はまだ遠いと思った。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "しあい ひ とお おも", "sentence_source": "generated"}, {"text": "遠い道を歩いて帰った。", "target_word": "遠い", "complexity_tier": "T3", "furigana": "とお みち ある かえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠く", "label": "活用"}, {"form": "遠かった", "label": "活用"}, {"form": "遠くて", "label": "活用"}, {"form": "遠さ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 距離や時間の間隔が大きいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sens