INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所から遠くなること。", "primary_collocate": null, "pronunciation": "はなれる", "ipa": "hanaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "危ないから線路から離れる。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "あぶ せんろ はな", "sentence_source": "generated"}, {"text": "火から離れて立ってください。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "ひ はな た", "sentence_source": "generated"}, {"text": "船がゆっくり港を離れた。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "ふね みなと はな", "sentence_source": "generated"}, {"text": "家を離れるのは寂しい。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "いえ はな さび", "sentence_source": "generated"}, {"text": "犬が私のそばを離れない。", "target_word": "離れない", "complexity_tier": "T3", "furigana": "いぬ わたし はな", "sentence_source": "generated"}, {"text": "駅から少し離れた店に行った。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "えき すこ はな みせ い", "sentence_source": "generated"}, {"text": "故郷を離れて三年になる。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "こきょう はな さんねん", "sentence_source": "generated"}, {"text": "車から離れて待っていた。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "くるま はな ま", "sentence_source": "generated"}, {"text": "列から離れると危ない。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "れつ はな あぶ", "sentence_source": "generated"}, {"text": "鳥が木の枝を離れた。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "とり き えだ はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "離れた", "label": "活用"}, {"form": "離れて", "label": "活用"}, {"form": "離れない", "label": "活用"}, {"form": "離れ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | ある場所から遠くへ移る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'