INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35947, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や場所との距離ができるように移動する。また、関係を絶つ。", "primary_collocate": null, "pronunciation": "はなれる", "ipa": "hanaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "親から離れて一人で暮らす。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "おや はな ひとり く", "sentence_source": "generated"}, {"text": "友だちと離れるのはつらい。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "とも はな", "sentence_source": "generated"}, {"text": "彼はチームを離れた。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "かれ はな", "sentence_source": "generated"}, {"text": "母のそばを離れたくない。", "target_word": "離れ", "complexity_tier": "T3", "furigana": "はは はな", "sentence_source": "generated"}, {"text": "家族と離れて働いている。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "かぞく はな はたら", "sentence_source": "generated"}, {"text": "政治から離れた生活をする。", "target_word": "離れた", "complexity_tier": "T3", "furigana": "せいじ はな せいかつ", "sentence_source": "generated"}, {"text": "子どもが親から離れる時期だ。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "こ おや はな じき", "sentence_source": "generated"}, {"text": "仲間から離れると不安になる。", "target_word": "離れる", "complexity_tier": "T3", "furigana": "なかま はな ふあん", "sentence_source": "generated"}, {"text": "彼女は町を離れて東京へ行った。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "かのじょ まち はな とうきょう い", "sentence_source": "generated"}, {"text": "二人の心は離れてしまった。", "target_word": "離れて", "complexity_tier": "T3", "furigana": "ふたり こころ はな", "sentence_source": "generated"}], "morphological_forms": [{"form": "離れた", "label": "活用"}, {"form": "離れて", "label": "活用"}, {"form": "離れられない", "label": "活用"}, {"form": "離れ離れ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人や場所から遠ざかる、関係を絶つ", "collocate_grounding": {"status": "no_source", "reason": "no col