INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35950, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いいほうに かわること", "primary_collocate": null, "pronunciation": "しんぽ", "ipa": "ɕimpo", "syllable_count": 3, "sentences": [{"text": "科学の進歩はとても速い。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "かがく しんぽ はや", "sentence_source": "generated"}, {"text": "君の日本語には進歩が見える。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "きみ にほんご しんぽ み", "sentence_source": "generated"}, {"text": "技術が大きく進歩した。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "ぎじゅつ おお しんぽ", "sentence_source": "generated"}, {"text": "毎日の練習で進歩できる。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "まいにち れんしゅう しんぽ", "sentence_source": "generated"}, {"text": "少しの進歩でもうれしい。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "すこ しんぽ", "sentence_source": "generated"}, {"text": "医学の進歩で病気が治る。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "いがく しんぽ びょうき なお", "sentence_source": "generated"}, {"text": "進歩のない練習はつまらない。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しんぽ れんしゅう", "sentence_source": "generated"}, {"text": "先生は私の進歩をほめた。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "せんせい わたし しんぽ", "sentence_source": "generated"}, {"text": "ピアノが前より進歩している。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "まえ しんぽ", "sentence_source": "generated"}, {"text": "社会の進歩を考えよう。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しゃかい しんぽ かんが", "sentence_source": "generated"}], "morphological_forms": [{"form": "進歩する", "label": "派生"}, {"form": "進歩した", "label": "活用"}, {"form": "進歩的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事がよいほうへ進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat