INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35942, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "変化", "is_correct": true, "explanation": "「へんか」で、前とちがうようになること。"}, {"text": "喧嘩", "is_correct": false, "explanation": "「けんか」。最初の音が「へ」でなく「け」。"}, {"text": "返事", "is_correct": false, "explanation": "「へんじ」。最後の音が「か」でなく「じ」。"}, {"text": "電化", "is_correct": false, "explanation": "「でんか」。最初の音が「で」。"}, {"text": "陛下", "is_correct": false, "explanation": "「へいか」。二つ目の音が「ん」でなく「い」。"}], "explanations": {"変化": "「へんか」で、前とちがうようになること。", "喧嘩": "「けんか」。最初の音が「へ」でなく「け」。", "返事": "「へんじ」。最後の音が「か」でなく「じ」。", "電化": "「でんか」。最初の音が「で」。", "陛下": "「へいか」。二つ目の音が「ん」でなく「い」。"}, "sentence_index": null, "correct_answer": "変化"}, "level_3": {"options": [{"text": "変化", "is_correct": true, "explanation": "「大きな変化があった」で、様子がちがってきたことを表す。"}, {"text": "机", "is_correct": false, "explanation": "物の名前で、「様子に〜があった」に合わない。"}, {"text": "名前", "is_correct": false, "explanation": "「町の様子に名前があった」は意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "具体物で、様子のちがいを表せない。"}], "explanations": {"変化": "「大きな変化があった」で、様子がちがってきたことを表す。", "机": "物の名前で、「様子に〜があった」に合わない。", "名前": "「町の様子に名前があった」は意味が通らない。", "時計": "具体物で、様子のちがいを表せない。"}, "sentence_index": 0, "correct_answer": "変化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この変化はとてもおいしい。", "explanation": "変化は食べ物ではないので「おいしい」と言えない。"}, {"text": "変化を三つ買って帰った。", "explanation": "変化は物ではないので買えない。"}, {"text": "私の変化は田中です。", "explanation": "変化は名前を表す言葉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_