INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35942, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「感じる」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「感じている」の目的語に「が」は使えず非文。"}, {"text": "に", "is_correct": false, "explanation": "「変化に毎日感じる」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「感じる」と合わない。"}], "correct_answer": "を", "explanations": {"を": "「感じる」の目的語を示す。", "が": "「感じている」の目的語に「が」は使えず非文。", "に": "「変化に毎日感じる」は不自然。", "へ": "方向を表し、「感じる」と合わない。"}, "error_tags": {"が": "subject_vs_object", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不変", "is_correct": true, "explanation": "変わらないことで、「変化」の反対。"}, {"text": "変更", "is_correct": false, "explanation": "変えること。反対ではなく近い意味。"}, {"text": "天気", "is_correct": false, "explanation": "変化とは反対の関係にない言葉。"}, {"text": "気持ち", "is_correct": false, "explanation": "心の状態で、反対語ではない。"}], "correct_answer": "不変", "explanations": {"不変": "変わらないことで、「変化」の反対。", "変更": "変えること。反対ではなく近い意味。", "天気": "変化とは反対の関係にない言葉。", "気持ち": "心の状態で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35942, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "変化", "is_correct": true, "explanation": "「へんか」。ちがうようになること。"}, {"text": "天下", "is_correct": false, "explanation": "「てんか」。はじめの音が「て」。"}, {"text": "戦火", "is_correct": false, "explanation": "「せんか」。はじめの音が「せ」。"}, {"text": "単価", "is_correct": false, "explanation": "「たんか」。はじめの音が「た」。"}], "explanations": {"変化": "「へんか」。ちがうようになること。", "天下": "「てんか」。はじめの音が「て」。", "戦火": "「せんか」。はじめの音が「せ」。", "単価": "「たんか」。はじめの音が「た」。"}, "sentence_index": null, "correct_answer": "変化"}, "level_3": {"options": [{"text": "変化", "is_correct": true, "explanation": "「変化していない」で、町が前と同じままだという意味。"}, {"text": "勉強", "is_correct": false, "explanation": "「町は勉強していない」は意味が通らない。"}, {"text": "料理", "is_correct": false, "explanation": "町が料理することはない。"}, {"text": "運動", "is_correct": false, "explanation": "町が運動することはない。"}], "explanations": {"変化": "「変化していない」で、町が前と同じままだという意味。", "勉強": "「町は勉強していない」は意味が通らない。", "料理": "町が料理することはない。", "運動": "町が運動することはない。"}, "sentence_index": 6, "correct_answer": "変化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "変化に乗って学校へ行く。", "explanation": "変化は乗り物ではない。"}, {"text": "変化の机をきれいにふいた。", "explanation": "変化は物の持ち主にならない。"}, {"text": "変化さんに手紙を書いた。", "explanation": "変化は人ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
