INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35944, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遠い", "is_correct": true, "explanation": "「とおい」。離れていること。"}, {"text": "多い", "is_correct": false, "explanation": "「おおい」。はじめの音が「お」。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」。はじめの音が「あ」。"}, {"text": "十日", "is_correct": false, "explanation": "「とおか」。最後の音が「か」。"}, {"text": "通り", "is_correct": false, "explanation": "「とおり」。最後の音が「り」。"}], "explanations": {"遠い": "「とおい」。離れていること。", "多い": "「おおい」。はじめの音が「お」。", "青い": "「あおい」。はじめの音が「あ」。", "十日": "「とおか」。最後の音が「か」。", "通り": "「とおり」。最後の音が「り」。"}, "sentence_index": null, "correct_answer": "遠い"}, "level_3": {"options": [{"text": "遠い", "is_correct": true, "explanation": "「家から遠い」で距離が大きいことを表す。"}, {"text": "甘い", "is_correct": false, "explanation": "味の言葉で、「家から」と合わない。"}, {"text": "赤い", "is_correct": false, "explanation": "色の言葉で、「家から」と合わない。"}, {"text": "うるさい", "is_correct": false, "explanation": "音の言葉で、距離を表さない。"}], "explanations": {"遠い": "「家から遠い」で距離が大きいことを表す。", "甘い": "味の言葉で、「家から」と合わない。", "赤い": "色の言葉で、「家から」と合わない。", "うるさい": "音の言葉で、距離を表さない。"}, "sentence_index": 0, "correct_answer": "遠い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープはとても遠い。", "explanation": "スープの味に「遠い」は使えない。"}, {"text": "この荷物はとても遠い。", "explanation": "重さに「遠い」は使えない。"}, {"text": "この本は重くて遠い。", "explanation": "本の性質に「遠い」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
