INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35945, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遠い", "is_correct": true, "explanation": "「とおい」。間が大きく離れている。"}, {"text": "多い", "is_correct": false, "explanation": "「おおい」。はじめの音がちがう。"}, {"text": "十日", "is_correct": false, "explanation": "「とおか」。最後の音がちがう。"}, {"text": "通り", "is_correct": false, "explanation": "「とおり」。最後の音がちがう。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」。はじめの音がちがう。"}], "explanations": {"遠い": "「とおい」。間が大きく離れている。", "多い": "「おおい」。はじめの音がちがう。", "十日": "「とおか」。最後の音がちがう。", "通り": "「とおり」。最後の音がちがう。", "青い": "「あおい」。はじめの音がちがう。"}, "sentence_index": null, "correct_answer": "遠い"}, "level_3": {"options": [{"text": "遠い", "is_correct": true, "explanation": "「本土から遠い」で距離が大きいことを表す。"}, {"text": "寒い", "is_correct": false, "explanation": "気温の言葉で、「本土から」と合わない。"}, {"text": "強い", "is_correct": false, "explanation": "力の言葉で、距離を表さない。"}, {"text": "若い", "is_correct": false, "explanation": "年齢の言葉で、島に合わない。"}], "explanations": {"遠い": "「本土から遠い」で距離が大きいことを表す。", "寒い": "気温の言葉で、「本土から」と合わない。", "強い": "力の言葉で、距離を表さない。", "若い": "年齢の言葉で、島に合わない。"}, "sentence_index": 0, "correct_answer": "遠い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は塩が遠い。", "explanation": "味の濃さに「遠い」は使えない。"}, {"text": "遠い荷物を持ち上げた。", "explanation": "重さは「遠い」でなく「重い」で表す。"}, {"text": "彼女は背が遠い。", "explanation": "身長は「高い」で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35945, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その島は本土から遠いかった。", "corrected_sentence": "その島は本土から遠かった。", "error_description": "い形容詞の過去形は「遠かった」で、「遠いかった」とは言わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "遠い", "is_correct": true, "explanation": "名詞「未来」を修飾する形。"}, {"text": "遠く", "is_correct": false, "explanation": "名詞を直接修飾できない形。"}, {"text": "遠かろう", "is_correct": false, "explanation": "推量形で、名詞の前に置けない。"}, {"text": "遠くて", "is_correct": false, "explanation": "て形で、名詞「未来」を直接修飾できない。"}], "correct_form": "遠い", "base_form": "遠い", "form_label": "連体形（辞書形）", "sentence_index": 1, "explanations": {"遠い": "名詞「未来」を修飾する形。", "遠く": "名詞を直接修飾できない形。", "遠かろう": "推量形で、名詞の前に置けない。", "遠くて": "て形で、名詞「未来」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
