INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "離れる", "is_correct": true, "explanation": "「はなれる」。場所から遠くなる。"}, {"text": "流れる", "is_correct": false, "explanation": "「ながれる」。はじめの音がちがう。"}, {"text": "話せる", "is_correct": false, "explanation": "「はなせる」。三つ目の音がちがう。"}, {"text": "晴れる", "is_correct": false, "explanation": "「はれる」。「な」の音がない。"}], "explanations": {"離れる": "「はなれる」。場所から遠くなる。", "流れる": "「ながれる」。はじめの音がちがう。", "話せる": "「はなせる」。三つ目の音がちがう。", "晴れる": "「はれる」。「な」の音がない。"}, "sentence_index": null, "correct_answer": "離れる"}, "level_3": {"options": [{"text": "離れる", "is_correct": true, "explanation": "危ないので線路から遠くへ移る、という意味。"}, {"text": "近づく", "is_correct": false, "explanation": "危ないのに線路に近づくのは意味が合わない。"}, {"text": "座る", "is_correct": false, "explanation": "「線路から座る」は言わない。"}, {"text": "食べる", "is_correct": false, "explanation": "「線路から食べる」は意味が通らない。"}], "explanations": {"離れる": "危ないので線路から遠くへ移る、という意味。", "近づく": "危ないのに線路に近づくのは意味が合わない。", "座る": "「線路から座る」は言わない。", "食べる": "「線路から食べる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "離れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝パンを離れて食べる。", "explanation": "パンを食べる動作に「離れる」は合わない。"}, {"text": "本を離れて読んだ。", "explanation": "読む対象に「離れる」は使えない。"}, {"text": "雨が離れて降ってきた。", "explanation": "雨が降る様子に「離れる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
