INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35946, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "離れる起点を示す。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「離れる」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を表し、非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「離れる」の起点にならない。"}], "correct_answer": "から", "explanations": {"から": "離れる起点を示す。", "に": "着点を表し、「離れる」と合わない。", "で": "場所・手段を表し、非文。", "へ": "方向を表し、「離れる」の起点にならない。"}, "error_tags": {"に": "source_vs_goal", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近づく", "is_correct": true, "explanation": "距離が小さくなること。「離れる」の反対。"}, {"text": "走る", "is_correct": false, "explanation": "動き方の言葉で、反対語ではない。"}, {"text": "休む", "is_correct": false, "explanation": "反対の関係にない言葉。"}, {"text": "立つ", "is_correct": false, "explanation": "姿勢の言葉で、反対語ではない。"}], "correct_answer": "近づく", "explanations": {"近づく": "距離が小さくなること。「離れる」の反対。", "走る": "動き方の言葉で、反対語ではない。", "休む": "反対の関係にない言葉。", "立つ": "姿勢の言葉で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df07b0d9-658b-4580-b45a-fb08be1a8f28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
