INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35951, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がより良い状態や段階に進むこと。", "primary_collocate": null, "pronunciation": "しんぽ", "ipa": "ɕimpo", "syllable_count": 3, "sentences": [{"text": "科学の進歩はとても速い。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "かがく しんぽ はや", "sentence_source": "generated"}, {"text": "英語が少し進歩した。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "えいご すこ しんぽ", "sentence_source": "generated"}, {"text": "毎日の練習で進歩を感じる。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "まいにち れんしゅう しんぽ かん", "sentence_source": "generated"}, {"text": "技術は今も進歩している。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "ぎじゅつ いま しんぽ", "sentence_source": "generated"}, {"text": "彼のピアノは大きく進歩した。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "かれ おお しんぽ", "sentence_source": "generated"}, {"text": "進歩のない毎日はつまらない。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しんぽ まいにち", "sentence_source": "generated"}, {"text": "先生は私の進歩をほめた。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "せんせい わたし しんぽ", "sentence_source": "generated"}, {"text": "医学の進歩で病気が治る。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "いがく しんぽ びょうき なお", "sentence_source": "generated"}, {"text": "少しずつでも進歩は進歩だ。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "すこ しんぽ しんぽ", "sentence_source": "generated"}, {"text": "チームは試合ごとに進歩している。", "target_word": "進歩", "complexity_tier": "T3", "furigana": "しあい しんぽ", "sentence_source": "generated"}], "morphological_forms": [{"form": "進歩する", "label": "派生"}, {"form": "進歩的", "label": "派生"}, {"form": "進歩した", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事がより良い方向に進むこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'c