INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35954, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものや意味を表すためのしるし。", "primary_collocate": null, "pronunciation": "きごう", "ipa": "kiɡoː", "syllable_count": 3, "sentences": [{"text": "この記号はどういう意味ですか。", "target_word": "記号", "complexity_tier": "T3", "furigana": "きごう いみ", "sentence_source": "generated"}, {"text": "地図には多くの記号がある。", "target_word": "記号", "complexity_tier": "T3", "furigana": "ちず おお きごう", "sentence_source": "generated"}, {"text": "答えに丸の記号をつけた。", "target_word": "記号", "complexity_tier": "T3", "furigana": "こた まる きごう", "sentence_source": "generated"}, {"text": "記号の意味を辞書で調べた。", "target_word": "記号", "complexity_tier": "T3", "furigana": "きごう いみ じしょ しら", "sentence_source": "generated"}, {"text": "数学では記号をよく使う。", "target_word": "記号", "complexity_tier": "T3", "furigana": "すうがく きごう つか", "sentence_source": "generated"}, {"text": "この記号は「止まれ」を表す。", "target_word": "記号", "complexity_tier": "T3", "furigana": "きごう と あらわ", "sentence_source": "generated"}, {"text": "パスワードに記号を入れてください。", "target_word": "記号", "complexity_tier": "T3", "furigana": "きごう い", "sentence_source": "generated"}, {"text": "天気の記号を覚えている。", "target_word": "記号", "complexity_tier": "T3", "furigana": "てんき きごう おぼ", "sentence_source": "generated"}, {"text": "記号だけで道がわかる。", "target_word": "記号", "complexity_tier": "T3", "furigana": "きごう みち", "sentence_source": "generated"}, {"text": "黒板に変な記号が書いてある。", "target_word": "記号", "complexity_tier": "T3", "furigana": "こくばん へん きごう か", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "助数詞"}, {"form": "つ", "label": "助数詞"}, {"form": "記号的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 意味を表すためのしるし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', '