INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35976, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ほしいものやしたいことを、強く願って手に入れようとする。", "primary_collocate": null, "pronunciation": "もとめる", "ipa": "motomeɾɯ", "syllable_count": 4, "sentences": [{"text": "彼は自由を求めている。", "target_word": "求め", "complexity_tier": "T3", "furigana": "かれ じゆう もと", "sentence_source": "generated"}, {"text": "人はみんな幸せを求める。", "target_word": "求める", "complexity_tier": "T3", "furigana": "ひと しあわ もと", "sentence_source": "generated"}, {"text": "多くの人が平和を求めた。", "target_word": "求め", "complexity_tier": "T3", "furigana": "おお ひと へいわ もと", "sentence_source": "generated"}, {"text": "彼女は新しい生活を求めて町を出た。", "target_word": "求め", "complexity_tier": "T3", "furigana": "かのじょ あたら せいかつ もと まち で", "sentence_source": "generated"}, {"text": "求める答えはまだ見つからない。", "target_word": "求める", "complexity_tier": "T3", "furigana": "もと こた み", "sentence_source": "generated"}, {"text": "ぼくはお金を求めていない。", "target_word": "求め", "complexity_tier": "T3", "furigana": "かね もと", "sentence_source": "generated"}, {"text": "動物は水を求めて川に来た。", "target_word": "求め", "complexity_tier": "T3", "furigana": "どうぶつ みず もと かわ き", "sentence_source": "generated"}, {"text": "彼は強さだけを求めた。", "target_word": "求め", "complexity_tier": "T3", "furigana": "かれ つよ もと", "sentence_source": "generated"}, {"text": "友達の助けを求めた。", "target_word": "求め", "complexity_tier": "T3", "furigana": "ともだち たす もと", "sentence_source": "generated"}, {"text": "求めるものは人それぞれだ。", "target_word": "求める", "complexity_tier": "T3", "furigana": "もと ひと", "sentence_source": "generated"}], "morphological_forms": [{"form": "求めた", "label": "活用"}, {"form": "求めて", "label": "活用"}, {"form": "求めない", "label": "活用"}, {"form": "求め", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | ほしいものを強く願う", "collocate_grounding": {"status": "no_source", "reason": "no collocate assert