INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35951, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "進歩", "is_correct": true, "explanation": "正解。読みは「しんぽ」。"}, {"text": "散歩", "is_correct": false, "explanation": "読みは「さんぽ」。「し」が「さ」に変わる一モーラ差。"}, {"text": "神秘", "is_correct": false, "explanation": "読みは「しんぴ」。「ぽ」が「ぴ」に変わる一モーラ差。"}, {"text": "尻尾", "is_correct": false, "explanation": "読みは「しっぽ」。「ん」が促音「っ」に変わる一モーラ差。"}, {"text": "新派", "is_correct": false, "explanation": "読みは「しんぱ」。「ぽ」が「ぱ」に変わる一モーラ差。"}], "explanations": {"進歩": "正解。読みは「しんぽ」。", "散歩": "読みは「さんぽ」。「し」が「さ」に変わる一モーラ差。", "神秘": "読みは「しんぴ」。「ぽ」が「ぴ」に変わる一モーラ差。", "尻尾": "読みは「しっぽ」。「ん」が促音「っ」に変わる一モーラ差。", "新派": "読みは「しんぱ」。「ぽ」が「ぱ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "進歩"}, "level_3": {"options": [{"text": "進歩", "is_correct": true, "explanation": "科学が良くなっていく速さを表し、文に合う。"}, {"text": "記憶", "is_correct": false, "explanation": "「科学の記憶が速い」は意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "科学に値段はなく、「速い」とも合わない。"}, {"text": "天気", "is_correct": false, "explanation": "科学の天気という言い方はない。"}], "explanations": {"進歩": "科学が良くなっていく速さを表し、文に合う。", "記憶": "「科学の記憶が速い」は意味が通らない。", "値段": "科学に値段はなく、「速い」とも合わない。", "天気": "科学の天気という言い方はない。"}, "sentence_index": 0, "correct_answer": "進歩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、公園を進歩する。", "explanation": "「進歩」は歩くことではない。「散歩」と混同している。"}, {"text": "事故で車がひどく進歩した。", "explanation": "悪くなることに「進歩」は使えない。"}, {"text": "このパンは進歩の味がする。", "explanation": "「進歩」は味を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d8a4192-0feb-46aa-ab65-f01cbe0e4465') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_w