INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35979, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "この位置に正しく入る助詞。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は目的語をとらないので「を」は不可。"}, {"text": "で", "is_correct": false, "explanation": "「複数の意味である」の形になり、「ある」の主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は存在の文に合わない。"}], "correct_answer": "が", "explanations": {"が": "この位置に正しく入る助詞。", "を": "「ある」は目的語をとらないので「を」は不可。", "で": "「複数の意味である」の形になり、「ある」の主語を示せない。", "へ": "方向を表す「へ」は存在の文に合わない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "単数", "is_correct": true, "explanation": "対義語。"}, {"text": "多数", "is_correct": false, "explanation": "「多数」は数が多いことで、対義語ではない。"}, {"text": "全部", "is_correct": false, "explanation": "すべてを表し、対義語ではない。"}, {"text": "半分", "is_correct": false, "explanation": "二つに分けた一方で、対義語ではない。"}], "correct_answer": "単数", "explanations": {"単数": "対義語。", "多数": "「多数」は数が多いことで、対義語ではない。", "全部": "すべてを表し、対義語ではない。", "半分": "二つに分けた一方で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df795526-5279-4a52-95fa-4a5b60addb95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35979, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "複数", "is_correct": true, "explanation": "音声どおりの語。"}, {"text": "梟", "is_correct": false, "explanation": "「ふくろう」と読み、三拍目「す」と「ろ」だけが違う。"}, {"text": "服従", "is_correct": false, "explanation": "「ふくじゅう」と読み、三拍目「す」と「じゅ」だけが違う。"}, {"text": "普通", "is_correct": false, "explanation": "「ふつう」と読み、「く」がなく「す」が「つ」になる。"}], "explanations": {"複数": "音声どおりの語。", "梟": "「ふくろう」と読み、三拍目「す」と「ろ」だけが違う。", "服従": "「ふくじゅう」と読み、三拍目「す」と「じゅ」だけが違う。", "普通": "「ふつう」と読み、「く」がなく「す」が「つ」になる。"}, "sentence_index": null, "correct_answer": "複数"}, "level_3": {"options": [{"text": "複数", "is_correct": true, "explanation": "文の意味に合う。"}, {"text": "雨", "is_correct": false, "explanation": "意味：駅の数を表せない。"}, {"text": "朝", "is_correct": false, "explanation": "意味：時間を表し、数を表さない。"}, {"text": "犬", "is_correct": false, "explanation": "意味：駅の数とは関係ない。"}], "explanations": {"複数": "文の意味に合う。", "雨": "意味：駅の数を表せない。", "朝": "意味：時間を表し、数を表さない。", "犬": "意味：駅の数とは関係ない。"}, "sentence_index": 6, "correct_answer": "複数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は一つしか話せない複数の言葉を話せる。", "explanation": "「複数」は二つ以上なので「一つしか」と矛盾する。"}, {"text": "彼は言葉を複数して話せる。", "explanation": "「複数」は「する」をつけて動詞にできない。"}, {"text": "彼は三本の複数の言葉を話せる。", "explanation": "助数詞の誤り：言葉を「本」で数えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df795526-5279-4a52-95fa-4a5b60addb95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
