INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36074, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを思い通りに動かしたり、止めたりすること。", "primary_collocate": null, "pronunciation": "せいぎょ", "ipa": "seːɡʲo", "syllable_count": 3, "sentences": [{"text": "この機械は、コンピューターで制御している。", "target_word": "制御", "complexity_tier": "T3", "furigana": "きかい せいぎょ", "sentence_source": "generated"}, {"text": "車の制御が急にきかなくなった。", "target_word": "制御", "complexity_tier": "T3", "furigana": "くるま せいぎょ きゅう", "sentence_source": "generated"}, {"text": "温度の制御はとても大切です。", "target_word": "制御", "complexity_tier": "T3", "furigana": "おんど せいぎょ たいせつ", "sentence_source": "generated"}, {"text": "ロボットを制御するのは難しい。", "target_word": "制御", "complexity_tier": "T3", "furigana": "せいぎょ むずか", "sentence_source": "generated"}, {"text": "彼は制御の仕事をしている。", "target_word": "制御", "complexity_tier": "T3", "furigana": "かれ せいぎょ しごと", "sentence_source": "generated"}, {"text": "信号は自動で制御されている。", "target_word": "制御", "complexity_tier": "T3", "furigana": "しんごう じどう せいぎょ", "sentence_source": "generated"}, {"text": "制御の方法を先生に聞いた。", "target_word": "制御", "complexity_tier": "T3", "furigana": "せいぎょ ほうほう せんせい き", "sentence_source": "generated"}, {"text": "水の量を制御して、畑に送る。", "target_word": "制御", "complexity_tier": "T3", "furigana": "みず りょう せいぎょ はたけ おく", "sentence_source": "generated"}, {"text": "この部屋で電気を制御できる。", "target_word": "制御", "complexity_tier": "T3", "furigana": "へや でんき せいぎょ", "sentence_source": "generated"}, {"text": "飛行機の制御は人が見ている。", "target_word": "制御", "complexity_tier": "T3", "furigana": "ひこうき せいぎょ ひと み", "sentence_source": "generated"}], "morphological_forms": [{"form": "制御する", "label": "派生"}, {"form": "制御装置", "label": "派生"}, {"form": "自動制御", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 機械などを思い通りに動かすこと", "collocate_grounding": {"status": "no_source", "reason": "no coll