INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36076, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ただそれだけ。ほかのことはないということ。", "primary_collocate": null, "pronunciation": "たんに", "ipa": "taɲɲi", "syllable_count": 3, "sentences": [{"text": "単に疲れているだけです。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん つか", "sentence_source": "generated"}, {"text": "それは単に私のミスだった。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん わたし", "sentence_source": "generated"}, {"text": "単に好きだから、絵をかいている。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん す え", "sentence_source": "generated"}, {"text": "彼は単に忘れていたらしい。", "target_word": "単に", "complexity_tier": "T3", "furigana": "かれ たん わす", "sentence_source": "generated"}, {"text": "単に遅れただけで、怒らないで。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん おく おこ", "sentence_source": "generated"}, {"text": "これは単に練習の問題です。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん れんしゅう もんだい", "sentence_source": "generated"}, {"text": "単にお金の話ではない。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん かね はなし", "sentence_source": "generated"}, {"text": "単に聞いてみたかっただけだ。", "target_word": "単に", "complexity_tier": "T3", "furigana": "たん き", "sentence_source": "generated"}, {"text": "勝つことは単に運ではない。", "target_word": "単に", "complexity_tier": "T3", "furigana": "か たん うん", "sentence_source": "generated"}, {"text": "彼女は単に静かな人だ。", "target_word": "単に", "complexity_tier": "T3", "furigana": "かのじょ たん しず ひと", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | ただそれだけだと限定する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d2af7-8600-4de1-873b-f31c902b6517') ON CONFLICT (sense_id, asset_type) 