INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36086, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かと何かの間に入って、つなぐもの。", "primary_collocate": null, "pronunciation": "ばいかい", "ipa": "baikai", "syllable_count": 4, "sentences": [{"text": "蚊は病気を媒介する虫だ。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "か びょうき ばいかい むし", "sentence_source": "generated"}, {"text": "言葉は人と人の媒介になる。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ことば ひと ひと ばいかい", "sentence_source": "generated"}, {"text": "この虫が病気の媒介をする。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "むし びょうき ばいかい", "sentence_source": "generated"}, {"text": "音楽を媒介に友達ができた。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "おんがく ばいかい ともだち", "sentence_source": "generated"}, {"text": "ネズミは病気を媒介することがある。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "びょうき ばいかい", "sentence_source": "generated"}, {"text": "手紙が二人の媒介だった。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "てがみ ふたり ばいかい", "sentence_source": "generated"}, {"text": "水が病気を媒介した。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "みず びょうき ばいかい", "sentence_source": "generated"}, {"text": "彼が媒介となって話が進んだ。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "かれ ばいかい はなし すす", "sentence_source": "generated"}, {"text": "媒介の役目はとても大きい。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ばいかい やくめ おお", "sentence_source": "generated"}, {"text": "本を媒介に考えを伝える。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ほん ばいかい かんが つた", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒介する", "label": "派生"}, {"form": "媒介者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 間に入って二つをつなぐもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fa