INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36087, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものの間にはいって、それらを関係づけるもの。", "primary_collocate": null, "pronunciation": "ばいかい", "ipa": "baikai", "syllable_count": 4, "sentences": [{"text": "友人の媒介で、二人は会った。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ゆうじん ばいかい ふたり あ", "sentence_source": "generated"}, {"text": "祭りが町と人の媒介になった。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "まつ まち ひと ばいかい", "sentence_source": "generated"}, {"text": "先生が媒介して、話し合いをした。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "せんせい ばいかい はな あ", "sentence_source": "generated"}, {"text": "言葉は心と心の媒介だ。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ことば こころ こころ ばいかい", "sentence_source": "generated"}, {"text": "絵を媒介に、気持ちを伝えた。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "え ばいかい きも つた", "sentence_source": "generated"}, {"text": "彼女は二つの国の媒介をした。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "かのじょ ふた くに ばいかい", "sentence_source": "generated"}, {"text": "スポーツは人をつなぐ媒介だ。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ひと ばいかい", "sentence_source": "generated"}, {"text": "店が農家と客の媒介となる。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "みせ のうか きゃく ばいかい", "sentence_source": "generated"}, {"text": "媒介する人がいて、助かった。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "ばいかい ひと たす", "sentence_source": "generated"}, {"text": "映画を媒介に、文化を知る。", "target_word": "媒介", "complexity_tier": "T3", "furigana": "えいが ばいかい ぶんか し", "sentence_source": "generated"}], "morphological_forms": [{"form": "媒介する", "label": "派生"}, {"form": "媒介者", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 二つの間で関係をつけるもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::js