INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36092, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるときから、あと。", "primary_collocate": null, "pronunciation": "いこう", "ipa": "ikoː", "syllable_count": 3, "sentences": [{"text": "五時以降は電話に出られない。", "target_word": "以降", "complexity_tier": "T3", "furigana": "ごじ いこう でんわ で", "sentence_source": "generated"}, {"text": "来週以降に会いましょう。", "target_word": "以降", "complexity_tier": "T3", "furigana": "らいしゅう いこう あ", "sentence_source": "generated"}, {"text": "それ以降、彼は来なくなった。", "target_word": "以降", "complexity_tier": "T3", "furigana": "いこう かれ こ", "sentence_source": "generated"}, {"text": "夜九時以降は静かにしてね。", "target_word": "以降", "complexity_tier": "T3", "furigana": "よる くじ いこう しず", "sentence_source": "generated"}, {"text": "明日以降の予定を教えて。", "target_word": "以降", "complexity_tier": "T3", "furigana": "あした いこう よてい おし", "sentence_source": "generated"}, {"text": "四月以降、新しい先生が来る。", "target_word": "以降", "complexity_tier": "T3", "furigana": "しがつ いこう あたら せんせい く", "sentence_source": "generated"}, {"text": "あの日以降、雨が続いている。", "target_word": "以降", "complexity_tier": "T3", "furigana": "ひ いこう あめ つづ", "sentence_source": "generated"}, {"text": "十時以降の入場はできません。", "target_word": "以降", "complexity_tier": "T3", "furigana": "じゅうじ いこう にゅうじょう", "sentence_source": "generated"}, {"text": "春以降、町が明るくなった。", "target_word": "以降", "complexity_tier": "T3", "furigana": "はる いこう まち あか", "sentence_source": "generated"}, {"text": "二年生以降は部活がある。", "target_word": "以降", "complexity_tier": "T3", "furigana": "にねんせい いこう ぶかつ", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | ある時点より後の時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0d2af7-8600-4de1-873b-f31c902b6517') O