INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36074, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "制御", "is_correct": true, "explanation": "正解。音も意味も目標語と一致する。"}, {"text": "正義", "is_correct": false, "explanation": "「正義」は一拍だけ音が違う別の語。"}, {"text": "逝去", "is_correct": false, "explanation": "「逝去」は一拍だけ音が違う別の語。"}, {"text": "鮮魚", "is_correct": false, "explanation": "「鮮魚」は一拍だけ音が違う別の語。"}, {"text": "成語", "is_correct": false, "explanation": "「成語」は一拍だけ音が違う別の語。"}], "explanations": {"制御": "正解。音も意味も目標語と一致する。", "正義": "「正義」は一拍だけ音が違う別の語。", "逝去": "「逝去」は一拍だけ音が違う別の語。", "鮮魚": "「鮮魚」は一拍だけ音が違う別の語。", "成語": "「成語」は一拍だけ音が違う別の語。"}, "sentence_index": null, "correct_answer": "制御"}, "level_3": {"options": [{"text": "制御", "is_correct": true, "explanation": "機械を思い通りに動かす意味で合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は食べ物を作ることで、機械の動きに合わない。"}, {"text": "製造", "is_correct": false, "explanation": "「コンピューターで製造している」では機械自体の動きにならない。"}, {"text": "清掃", "is_correct": false, "explanation": "掃除の意味で文に合わない。"}], "explanations": {"制御": "機械を思い通りに動かす意味で合う。", "料理": "料理は食べ物を作ることで、機械の動きに合わない。", "製造": "「コンピューターで製造している」では機械自体の動きにならない。", "清掃": "掃除の意味で文に合わない。"}, "sentence_index": 0, "correct_answer": "制御"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は毎日、宿題を制御している。", "explanation": "宿題は動かす対象ではない。"}, {"text": "友達と公園で制御した。", "explanation": "遊びの意味では使えない。"}, {"text": "このケーキはとても制御だ。", "explanation": "形容詞のようには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d760222-fd2a-408f-a7b3-761330ca01f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
