INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36100, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "音の大きさや小ささのこと。", "primary_collocate": null, "pronunciation": "きょうじゃく", "ipa": "kʲoːdʑakɯ", "syllable_count": 4, "sentences": [{"text": "声の強弱に気をつけて話そう。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "こえ きょうじゃく き はな", "sentence_source": "generated"}, {"text": "この曲は音の強弱がはっきりしている。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "きょく おと きょうじゃく", "sentence_source": "generated"}, {"text": "強弱をつけて歌うと上手に聞こえる。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "きょうじゃく うた じょうず き", "sentence_source": "generated"}, {"text": "太鼓の強弱が心に響いた。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "たいこ きょうじゃく こころ ひび", "sentence_source": "generated"}, {"text": "先生は音の強弱を教えてくれた。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "せんせい おと きょうじゃく おし", "sentence_source": "generated"}, {"text": "強弱のない読み方はつまらない。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "きょうじゃく よ かた", "sentence_source": "generated"}, {"text": "ピアノの強弱が難しい。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "きょうじゃく むずか", "sentence_source": "generated"}, {"text": "彼の声には強弱がある。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "かれ こえ きょうじゃく", "sentence_source": "generated"}, {"text": "音の強弱を聞き分けてみよう。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "おと きょうじゃく き わ", "sentence_source": "generated"}, {"text": "強弱のつけ方が上手な人の演奏を聞いた。", "target_word": "強弱", "complexity_tier": "T3", "furigana": "きょうじゃく かた じょうず ひと えんそう き", "sentence_source": "generated"}], "morphological_forms": [{"form": "強弱", "label": "派生"}, {"form": "強弱をつける", "label": "派生"}, {"form": "強弱記号", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 音の大きい小さいの度合い", "collocate_grounding": {"status": "no_source", "reas