INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36104, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを人に知らせたり、やってほしいことを伝えること。", "primary_collocate": null, "pronunciation": "しじ", "ipa": "ɕidʑi", "syllable_count": 2, "sentences": [{"text": "先生の指示に従ってください。", "target_word": "指示", "complexity_tier": "T3", "furigana": "せんせい しじ したが", "sentence_source": "generated"}, {"text": "係の人が指示を出した。", "target_word": "指示", "complexity_tier": "T3", "furigana": "かかり ひと しじ だ", "sentence_source": "generated"}, {"text": "指示を待ってから動こう。", "target_word": "指示", "complexity_tier": "T3", "furigana": "しじ ま うご", "sentence_source": "generated"}, {"text": "店長が新人に指示している。", "target_word": "指示", "complexity_tier": "T3", "furigana": "てんちょう しんじん しじ", "sentence_source": "generated"}, {"text": "その指示はわかりにくかった。", "target_word": "指示", "complexity_tier": "T3", "furigana": "しじ", "sentence_source": "generated"}, {"text": "指示どおりに箱を運んだ。", "target_word": "指示", "complexity_tier": "T3", "furigana": "しじ はこ はこ", "sentence_source": "generated"}, {"text": "監督は選手に細かく指示した。", "target_word": "指示", "complexity_tier": "T3", "furigana": "かんとく せんしゅ こま しじ", "sentence_source": "generated"}, {"text": "指示がないので困っている。", "target_word": "指示", "complexity_tier": "T3", "furigana": "しじ こま", "sentence_source": "generated"}, {"text": "係の人の指示を聞いてから歩いた。", "target_word": "指示", "complexity_tier": "T3", "furigana": "かかり ひと しじ き ある", "sentence_source": "generated"}, {"text": "母の指示で部屋を片づけた。", "target_word": "指示", "complexity_tier": "T3", "furigana": "はは しじ へや かた", "sentence_source": "generated"}], "morphological_forms": [{"form": "指示する", "label": "派生"}, {"form": "指示した", "label": "活用"}, {"form": "指示書", "label": "派生"}, {"form": "指示を出す", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人にやることを伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserte