INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38824, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少量", "is_correct": true, "explanation": "「しょうりょう」。数や量が少ないこと。"}, {"text": "数量", "is_correct": false, "explanation": "「すうりょう」。最初の拍が違う別の語。"}, {"text": "重量", "is_correct": false, "explanation": "「じゅうりょう」。重さのことで、最初の拍が違う。"}, {"text": "終了", "is_correct": false, "explanation": "「しゅうりょう」。終わることで、最初の拍（しょ/しゅ）が違う。"}, {"text": "容量", "is_correct": false, "explanation": "「ようりょう」。入る量のことで、最初の拍が違う。"}], "explanations": {"少量": "「しょうりょう」。数や量が少ないこと。", "数量": "「すうりょう」。最初の拍が違う別の語。", "重量": "「じゅうりょう」。重さのことで、最初の拍が違う。", "終了": "「しゅうりょう」。終わることで、最初の拍（しょ/しゅ）が違う。", "容量": "「ようりょう」。入る量のことで、最初の拍が違う。"}, "sentence_index": null, "correct_answer": "少量"}, "level_3": {"options": [{"text": "少量", "is_correct": true, "explanation": "塩を少しだけ入れるという意味になる。"}, {"text": "少年", "is_correct": false, "explanation": "男の子のことで、塩の量を表せない。"}, {"text": "少数", "is_correct": false, "explanation": "人や物の数が少ないことで、塩の量には使わない。"}, {"text": "小型", "is_correct": false, "explanation": "形が小さいことで、量を表さない。"}], "explanations": {"少量": "塩を少しだけ入れるという意味になる。", "少年": "男の子のことで、塩の量を表せない。", "少数": "人や物の数が少ないことで、塩の量には使わない。", "小型": "形が小さいことで、量を表さない。"}, "sentence_index": 0, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は少量な人で、あまり話さない。", "explanation": "少量は物の量に使い、人の性格には使わない。"}, {"text": "このビルはとても少量だ。", "explanation": "建物の大きさには少量を使わない。"}, {"text": "少量に走ったので疲れた。", "explanation": "少量は動作の様子を表す副詞としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd41cd82-e7d9-4975-9b41-871c52232248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
