INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38824, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「赤くなる」の主語「顔」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「赤くなる」は自動詞なので、目的語の「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「顔で赤くなった」では主語が示されず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」はこの位置に入らない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「赤くなる」の主語「顔」を示す。", "を": "「赤くなる」は自動詞なので、目的語の「を」は使えない。", "で": "「顔で赤くなった」では主語が示されず不自然。", "へ": "方向を表す「へ」はこの位置に入らない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大量", "is_correct": true, "explanation": "量がとても多いことで、少量の反対。"}, {"text": "微量", "is_correct": false, "explanation": "ごくわずかな量で、少量に近い意味。"}, {"text": "重量", "is_correct": false, "explanation": "重さのことで、反対の意味ではない。"}, {"text": "分量", "is_correct": false, "explanation": "量そのものを指し、反対語ではない。"}], "correct_answer": "大量", "explanations": {"大量": "量がとても多いことで、少量の反対。", "微量": "ごくわずかな量で、少量に近い意味。", "重量": "重さのことで、反対の意味ではない。", "分量": "量そのものを指し、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd41cd82-e7d9-4975-9b41-871c52232248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
