INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38825, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少量", "is_correct": true, "explanation": "「しょうりょう」。わずかな量。"}, {"text": "重量", "is_correct": false, "explanation": "「じゅうりょう」。最初の拍が違う。"}, {"text": "要領", "is_correct": false, "explanation": "「ようりょう」。最初の拍が違う。"}, {"text": "数量", "is_correct": false, "explanation": "「すうりょう」。最初の拍が違う。"}, {"text": "修了", "is_correct": false, "explanation": "「しゅうりょう」。課程を終えること。二拍目が違う。"}], "explanations": {"少量": "「しょうりょう」。わずかな量。", "重量": "「じゅうりょう」。最初の拍が違う。", "要領": "「ようりょう」。最初の拍が違う。", "数量": "「すうりょう」。最初の拍が違う。", "修了": "「しゅうりょう」。課程を終えること。二拍目が違う。"}, "sentence_index": null, "correct_answer": "少量"}, "level_3": {"options": [{"text": "少量", "is_correct": true, "explanation": "水をわずかずつ足すという意味になる。"}, {"text": "少年", "is_correct": false, "explanation": "男の子のことで意味が通らない。"}, {"text": "小声", "is_correct": false, "explanation": "小さい声のことで、水と合わない。"}, {"text": "少数", "is_correct": false, "explanation": "数に使う語で、水の量には合わない。"}], "explanations": {"少量": "水をわずかずつ足すという意味になる。", "少年": "男の子のことで意味が通らない。", "小声": "小さい声のことで、水と合わない。", "少数": "数に使う語で、水の量には合わない。"}, "sentence_index": 6, "correct_answer": "少量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄は少量な性格で、すぐ怒る。", "explanation": "性格には少量を使わない。"}, {"text": "この部屋は少量なので狭い。", "explanation": "部屋の広さには少量を使わない。"}, {"text": "少量に話してください。", "explanation": "話し方を表す語として少量は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd41cd82-e7d9-4975-9b41-871c52232248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
