INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38825, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「加える」の対象「砂糖」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「加える」の目的語は「が」で示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」では加えた物が示せない。"}, {"text": "より", "is_correct": false, "explanation": "比べる「より」はこの文に入らない。"}], "correct_answer": "を", "explanations": {"を": "「加える」の対象「砂糖」を示す。", "が": "「加える」の目的語は「が」で示せない。", "へ": "「へ」では加えた物が示せない。", "より": "比べる「より」はこの文に入らない。"}, "error_tags": {"が": "object_marking", "へ": "direction", "より": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多量", "is_correct": true, "explanation": "量が多いことで、少量の反対。"}, {"text": "微量", "is_correct": false, "explanation": "ごくわずかな量で、少量に近い。"}, {"text": "分量", "is_correct": false, "explanation": "量そのもので、反対語ではない。"}, {"text": "適量", "is_correct": false, "explanation": "ちょうどよい量で、反対語ではない。"}], "correct_answer": "多量", "explanations": {"多量": "量が多いことで、少量の反対。", "微量": "ごくわずかな量で、少量に近い。", "分量": "量そのもので、反対語ではない。", "適量": "ちょうどよい量で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd41cd82-e7d9-4975-9b41-871c52232248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
