INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38868, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "時間がたつこと。", "primary_collocate": null, "pronunciation": "けいか", "ipa": "keːka", "syllable_count": 3, "sentences": [{"text": "出発から一時間が経過した。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "時間の経過がとても早く感じる。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "三日が経過しても連絡がない。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "経過した時間を記録している。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "時間の経過を忘れて本を読んだ。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "試合開始から十分が経過した。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "半年が経過して、仕事にも慣れた。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "一年が経過して町が変わった。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "時間が経過すると気持ちも落ち着く。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "五分経過したら火を止めてください。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}], "morphological_forms": [{"form": "経過する", "label": "派生"}, {"form": "経過時間", "label": "派生"}, {"form": "経過した", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 時間が過ぎていくこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9efc84-6fc6-414d-9166