INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38869, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が時間とともに進み、変わっていくこと。", "primary_collocate": null, "pronunciation": "けいか", "ipa": "keːka", "syllable_count": 3, "sentences": [{"text": "手術後の経過は順調だそうだ。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "試合の経過をラジオで聞いた。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "病気の経過を医者に話した。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "経過がよければ来週退院できる。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "実験の経過をノートに書いている。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "祖母のけがの経過が心配だ。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "会議の経過を先生に報告した。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "経過を見てから次の手を決めよう。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "選挙の経過をテレビで見ている。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}, {"text": "その後の経過を教えてください。", "target_word": "経過", "complexity_tier": "T3", "furigana": "けいか", "sentence_source": "generated"}], "morphological_forms": [{"form": "経過報告", "label": "派生"}, {"form": "途中経過", "label": "派生"}, {"form": "経過観察", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の進み具合や移り変わり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9efc84-6f