INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51437, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "病気やけがを治すために飲んだり塗ったりするもの。", "primary_collocate": "飲む", "pronunciation": "くすり", "ipa": "kɯsɯɾi", "syllable_count": 3, "sentences": [{"text": "毎朝ご飯の後に薬を飲む。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "この薬は苦くて飲みにくい。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "薬が効いて熱が下がった。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "かぜの薬を買いに行った。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "薬を飲んだらすぐ寝なさい。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "母が傷に薬を塗ってくれた。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "薬の量を間違えないでね。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "この薬はよく効くと評判だ。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "薬局で目の薬をもらった。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}, {"text": "薬を飲み忘れてしまった。", "target_word": "薬", "complexity_tier": "T3", "furigana": "くすり", "sentence_source": "generated"}], "morphological_forms": [{"form": "錠", "label": "助数詞"}, {"form": "薬屋", "label": "派生"}, {"form": "飲み薬", "label": "派生"}, {"form": "薬箱", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 病気を治すために使うもの", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL,