INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41274, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "同じ親から生まれた、自分より年上の男のきょうだい。", "primary_collocate": null, "pronunciation": "あに", "ipa": "ani", "syllable_count": 2, "sentences": [{"text": "兄はサッカーが上手だ。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "私には兄が二人いる。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄の部屋はいつもきれいだ。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "昨日、兄と映画を見に行った。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄に宿題を手伝ってもらった。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄は今、大学で勉強している。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄のくつを借りて出かけた。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄が作るカレーはおいしい。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄とけんかして少し悲しい。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "私は兄より背が高くなった。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}], "morphological_forms": [{"form": "人", "label": "助数詞"}, {"form": "兄弟", "label": "派生"}, {"form": "お兄さん", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "名詞 | 自分より年上の男のきょうだい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9efc84-6fc6-414d-9166-5df9e6b2aa48') ON CONFLICT