INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41275, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "同じ両親から生まれた年上の男性のきょうだい。", "primary_collocate": null, "pronunciation": "あに", "ipa": "ani", "syllable_count": 2, "sentences": [{"text": "兄は東京の会社で働いている。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄から久しぶりに手紙が来た。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄の意見はいつも正しいと思う。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "結婚した兄に子どもが生まれた。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄を尊敬している。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄と私は五つ年が離れている。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄の車で駅まで送ってもらった。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄は父によく似ている。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "困ったときは兄に相談する。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}, {"text": "兄が家を出て少しさびしい。", "target_word": "兄", "complexity_tier": "T3", "furigana": "あに", "sentence_source": "generated"}], "morphological_forms": [{"form": "人", "label": "助数詞"}, {"form": "兄弟", "label": "派生"}, {"form": "お兄様", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "名詞 | 両親を同じくする年上の男性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9efc84-6fc6-414d-9166-5df9e6b2aa48') ON CONFLICT