INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41278, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "気持ちや景色を、リズムのある短いことばで表したもの。", "primary_collocate": "書く", "pronunciation": "し", "ipa": "ɕi", "syllable_count": 1, "sentences": [{"text": "国語の授業で詩を書いた。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "この詩は春の景色を歌っている。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "好きな詩を声に出して読んだ。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "彼女の詩はとても美しい。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "詩の意味を考えるのは楽しい。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "姉は毎晩ノートに詩を書く。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "有名な詩を一つ覚えた。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "この詩を読むと元気が出る。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "詩のコンテストに応募した。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}, {"text": "短い詩でも心が伝わる。", "target_word": "詩", "complexity_tier": "T3", "furigana": "し", "sentence_source": "generated"}], "morphological_forms": [{"form": "編", "label": "助数詞"}, {"form": "詩人", "label": "派生"}, {"form": "詩集", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ことばを並べてリズムで表す作品", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9efc84-6fc6-414d-9166-5df9e6b2aa48') ON