INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38868, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "経過", "is_correct": true, "explanation": "正解。「経過」（けいか）。"}, {"text": "成果", "is_correct": false, "explanation": "「成果」は「せいか」と読み、一拍目（け→せ）が違う。"}, {"text": "景気", "is_correct": false, "explanation": "「景気」は「けいき」と読み、三拍目（か→き）が違う。"}, {"text": "結果", "is_correct": false, "explanation": "「結果」は「けっか」と読み、二拍目（い→促音）が違う。"}, {"text": "開花", "is_correct": false, "explanation": "「開花」は「かいか」と読み、一拍目（け→か）が違う。"}], "explanations": {"経過": "正解。「経過」（けいか）。", "成果": "「成果」は「せいか」と読み、一拍目（け→せ）が違う。", "景気": "「景気」は「けいき」と読み、三拍目（か→き）が違う。", "結果": "「結果」は「けっか」と読み、二拍目（い→促音）が違う。", "開花": "「開花」は「かいか」と読み、一拍目（け→か）が違う。"}, "sentence_index": null, "correct_answer": "経過"}, "level_3": {"options": [{"text": "経過", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "完成", "is_correct": false, "explanation": "意味：時間は「完成」するものではない。"}, {"text": "出席", "is_correct": false, "explanation": "項構造：「一時間が出席する」は主語が合わない。"}, {"text": "到着", "is_correct": false, "explanation": "意味：時間が「到着」するとは言わない。"}], "explanations": {"経過": "正解。文の意味に合う。", "完成": "意味：時間は「完成」するものではない。", "出席": "項構造：「一時間が出席する」は主語が合わない。", "到着": "意味：時間が「到着」するとは言わない。"}, "sentence_index": 0, "correct_answer": "経過"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間が経過を早く感じる。", "explanation": "助詞の混同：「時間の経過を」とすべき。"}, {"text": "一時間が経過するたった。", "explanation": "活用の誤り：「経過した」とすべき。"}, {"text": "経過な時間を記録している。", "explanation": "品詞の誤り：「経過」は名詞・する動詞で、「な」で修飾しない。「経過した」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21163ec1-1ace-450d-9f3b-7c45f3d65650') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.v