INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41275, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兄", "is_correct": true, "explanation": "正解。「兄」（あに）。"}, {"text": "穴", "is_correct": false, "explanation": "「穴」は「あな」と読み、二拍目（に→な）が違う。"}, {"text": "谷", "is_correct": false, "explanation": "「谷」は「たに」と読み、一拍目（あ→た）が違う。"}, {"text": "鰐", "is_correct": false, "explanation": "「鰐」は「わに」と読み、一拍目（あ→わ）が違う。"}, {"text": "味", "is_correct": false, "explanation": "「味」は「あじ」と読み、二拍目（に→じ）が違う。"}], "explanations": {"兄": "正解。「兄」（あに）。", "穴": "「穴」は「あな」と読み、二拍目（に→な）が違う。", "谷": "「谷」は「たに」と読み、一拍目（あ→た）が違う。", "鰐": "「鰐」は「わに」と読み、一拍目（あ→わ）が違う。", "味": "「味」は「あじ」と読み、二拍目（に→じ）が違う。"}, "sentence_index": null, "correct_answer": "兄"}, "level_3": {"options": [{"text": "兄", "is_correct": true, "explanation": "正解。文の意味に合う。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は会社で働かない。"}, {"text": "本", "is_correct": false, "explanation": "意味：本は働かない。"}, {"text": "空", "is_correct": false, "explanation": "意味：空は会社で働かない。"}], "explanations": {"兄": "正解。文の意味に合う。", "机": "意味：机は会社で働かない。", "本": "意味：本は働かない。", "空": "意味：空は会社で働かない。"}, "sentence_index": 0, "correct_answer": "兄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄を二冊尊敬している。", "explanation": "助数詞の誤り：「冊」は本を数える。"}, {"text": "兄で手紙が来た。", "explanation": "助詞の混同：「兄から」とすべき。"}, {"text": "兄は私より年下で、結婚した。", "explanation": "意味の誤り：「兄」は自分より年上の男のきょうだい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21163ec1-1ace-450d-9f3b-7c45f3d65650') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
