INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41300, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がくらしたり休んだりする、家の中の場所。", "primary_collocate": null, "pronunciation": "へや", "ipa": "heja", "syllable_count": 2, "sentences": [{"text": "私の部屋は二階にあります。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "わたし へや にかい", "sentence_source": "generated"}, {"text": "部屋をきれいに掃除した。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや そうじ", "sentence_source": "generated"}, {"text": "この部屋はとても明るい。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや あか", "sentence_source": "generated"}, {"text": "弟は自分の部屋で寝ている。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "おとうと じぶん へや ね", "sentence_source": "generated"}, {"text": "部屋の電気を消してください。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや でんき け", "sentence_source": "generated"}, {"text": "広い部屋に住みたいです。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "ひろ へや す", "sentence_source": "generated"}, {"text": "部屋が寒いので窓を閉めた。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや さむ まど し", "sentence_source": "generated"}, {"text": "姉の部屋には本がたくさんある。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "あね へや ほん", "sentence_source": "generated"}, {"text": "新しい部屋を探しています。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "あたら へや さが", "sentence_source": "generated"}, {"text": "部屋に入る前にノックをする。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや はい まえ", "sentence_source": "generated"}], "morphological_forms": [{"form": "部屋", "label": "助数詞"}, {"form": "一部屋", "label": "派生"}, {"form": "子ども部屋", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 家の中で人がくらす場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v