INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41301, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物の中で、壁や床で区切られた空間。人が住んだり物を置いたりする。", "primary_collocate": null, "pronunciation": "へや", "ipa": "heja", "syllable_count": 2, "sentences": [{"text": "ホテルの部屋から海が見えた。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや うみ み", "sentence_source": "generated"}, {"text": "会議は三階の部屋で行う。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "かいぎ さんがい へや おこな", "sentence_source": "generated"}, {"text": "この家には部屋が四つある。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "いえ へや よっ", "sentence_source": "generated"}, {"text": "部屋の中は静かだった。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや なか しず", "sentence_source": "generated"}, {"text": "荷物を隣の部屋に運んだ。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "にもつ となり へや はこ", "sentence_source": "generated"}, {"text": "部屋を借りて一人で住む。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや か ひとり す", "sentence_source": "generated"}, {"text": "この部屋は物置に使っている。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや ものおき つか", "sentence_source": "generated"}, {"text": "友だちと同じ部屋に泊まった。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "とも おな へや と", "sentence_source": "generated"}, {"text": "部屋のかべに絵をかけた。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "へや え", "sentence_source": "generated"}, {"text": "駅に近い部屋は家賃が高い。", "target_word": "部屋", "complexity_tier": "T3", "furigana": "えき ちか へや やちん たか", "sentence_source": "generated"}], "morphological_forms": [{"form": "二部屋", "label": "助数詞"}, {"form": "部屋代", "label": "派生"}, {"form": "相部屋", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 建物内の区切られた空間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'cl