INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41350, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "机で書類を整理したり計算したりする仕事。", "primary_collocate": null, "pronunciation": "じむ", "ipa": "dʑimɯ", "syllable_count": 2, "sentences": [{"text": "母は会社で事務をしている。", "target_word": "事務", "complexity_tier": "T3", "furigana": "はは かいしゃ じむ", "sentence_source": "generated"}, {"text": "事務の仕事は細かい。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ しごと こま", "sentence_source": "generated"}, {"text": "毎日パソコンで事務をする。", "target_word": "事務", "complexity_tier": "T3", "furigana": "まいにち じむ", "sentence_source": "generated"}, {"text": "事務が得意な人をさがす。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ とくい ひと", "sentence_source": "generated"}, {"text": "午後は事務を片づけた。", "target_word": "事務", "complexity_tier": "T3", "furigana": "ごご じむ かた", "sentence_source": "generated"}, {"text": "事務にはなれています。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ", "sentence_source": "generated"}, {"text": "姉は事務の仕事を始めた。", "target_word": "事務", "complexity_tier": "T3", "furigana": "あね じむ しごと はじ", "sentence_source": "generated"}, {"text": "事務のミスに気をつけて。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ き", "sentence_source": "generated"}, {"text": "今日は事務がたくさんある。", "target_word": "事務", "complexity_tier": "T3", "furigana": "きょう じむ", "sentence_source": "generated"}, {"text": "事務より外の仕事が好きだ。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ そと しごと す", "sentence_source": "generated"}], "morphological_forms": [{"form": "事務所", "label": "派生"}, {"form": "事務員", "label": "派生"}, {"form": "事務的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 机で書類を扱う仕事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL,