INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41351, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会社などで、書類の作成や整理、データ入力などの業務。", "primary_collocate": null, "pronunciation": "じむ", "ipa": "dʑimɯ", "syllable_count": 2, "sentences": [{"text": "書類は事務の人に出してください。", "target_word": "事務", "complexity_tier": "T3", "furigana": "しょるい じむ ひと だ", "sentence_source": "generated"}, {"text": "会社の事務で書類を作った。", "target_word": "事務", "complexity_tier": "T3", "furigana": "かいしゃ じむ しょるい つく", "sentence_source": "generated"}, {"text": "彼は事務を担当している。", "target_word": "事務", "complexity_tier": "T3", "furigana": "かれ じむ たんとう", "sentence_source": "generated"}, {"text": "事務の手続きに時間がかかる。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ てつづ じかん", "sentence_source": "generated"}, {"text": "会社の事務を手伝った。", "target_word": "事務", "complexity_tier": "T3", "furigana": "かいしゃ じむ てつだ", "sentence_source": "generated"}, {"text": "事務の仕事でデータを入力する。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ しごと にゅうりょく", "sentence_source": "generated"}, {"text": "新しい事務の方法を考えた。", "target_word": "事務", "complexity_tier": "T3", "furigana": "あたら じむ ほうほう かんが", "sentence_source": "generated"}, {"text": "学校の事務に電話をかけた。", "target_word": "事務", "complexity_tier": "T3", "furigana": "がっこう じむ でんわ", "sentence_source": "generated"}, {"text": "事務が遅れて困っている。", "target_word": "事務", "complexity_tier": "T3", "furigana": "じむ おく こま", "sentence_source": "generated"}, {"text": "彼女は銀行で事務をしている。", "target_word": "事務", "complexity_tier": "T3", "furigana": "かのじょ ぎんこう じむ", "sentence_source": "generated"}], "morphological_forms": [{"form": "事務所", "label": "派生"}, {"form": "事務員", "label": "派生"}, {"form": "事務局", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 会社での書類作成などの業務", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sen