INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42902, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間が食べ物や仕事のために飼う動物のことです。", "primary_collocate": null, "pronunciation": "かちく", "ipa": "katɕikɯ", "syllable_count": 3, "sentences": [{"text": "祖父の農場には家畜が多い。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "そふ のうじょう かちく おお", "sentence_source": "generated"}, {"text": "牛や豚は家畜です。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "うし ぶた かちく", "sentence_source": "generated"}, {"text": "毎朝、家畜にえさをあげる。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "まいあさ かちく", "sentence_source": "generated"}, {"text": "大雪で家畜が寒がっている。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "おおゆき かちく さむ", "sentence_source": "generated"}, {"text": "家畜の世話はとても大変だ。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "かちく せわ たいへん", "sentence_source": "generated"}, {"text": "村の人は家畜を大切にしている。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "むら ひと かちく たいせつ", "sentence_source": "generated"}, {"text": "ヤギは昔からの家畜だ。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "むかし かちく", "sentence_source": "generated"}, {"text": "家畜小屋の掃除を手伝った。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "かちくごや そうじ てつだ", "sentence_source": "generated"}, {"text": "この島では家畜を飼う人が多い。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "しま かちく か ひと おお", "sentence_source": "generated"}, {"text": "病気の家畜を獣医がみた。", "target_word": "家畜", "complexity_tier": "T3", "furigana": "びょうき かちく じゅうい", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "助数詞"}, {"form": "家畜小屋", "label": "派生"}, {"form": "家畜化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が飼う牛や豚などの動物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::j