INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51415, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "だれかがしていることを、いっしょにやってあげることです。", "primary_collocate": null, "pronunciation": "てつだい", "ipa": "tetsɯdai", "syllable_count": 4, "sentences": [{"text": "母の手伝いで皿を洗った。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "はは てつだ さら あら", "sentence_source": "generated"}, {"text": "引っ越しの手伝いに行く。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "ひ こ てつだ い", "sentence_source": "generated"}, {"text": "君の手伝いがあって助かった。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "きみ てつだ たす", "sentence_source": "generated"}, {"text": "弟は家の手伝いが好きだ。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "おとうと いえ てつだ す", "sentence_source": "generated"}, {"text": "祭りの手伝いを頼まれた。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "まつ てつだ たの", "sentence_source": "generated"}, {"text": "手伝いが必要なら言ってね。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "てつだ ひつよう い", "sentence_source": "generated"}, {"text": "友だちの手伝いで宿題が早く終わった。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "とも てつだ しゅくだい はや お", "sentence_source": "generated"}, {"text": "店の手伝いをして、お金をもらった。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "みせ てつだ かね", "sentence_source": "generated"}, {"text": "祖母の畑の手伝いは楽しい。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "そぼ はたけ てつだ たの", "sentence_source": "generated"}, {"text": "手伝いに来てくれてありがとう。", "target_word": "手伝い", "complexity_tier": "T3", "furigana": "てつだ き", "sentence_source": "generated"}], "morphological_forms": [{"form": "お手伝い", "label": "派生"}, {"form": "手伝う", "label": "派生"}, {"form": "手伝いさん", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人の仕事を助けること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for