INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51435, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人が病気やけがをしたときに、行くところです。", "primary_collocate": null, "pronunciation": "びょういん", "ipa": "bjoːiɴ", "syllable_count": 4, "sentences": [{"text": "熱が出たので病院へ行った。", "target_word": "病院", "complexity_tier": "T3", "furigana": "ねつ で びょういん い", "sentence_source": "generated"}, {"text": "駅の近くに大きな病院がある。", "target_word": "病院", "complexity_tier": "T3", "furigana": "えき ちか おお びょういん", "sentence_source": "generated"}, {"text": "病院の待合室は混んでいた。", "target_word": "病院", "complexity_tier": "T3", "furigana": "びょういん まちあいしつ こ", "sentence_source": "generated"}, {"text": "祖母は今、病院にいる。", "target_word": "病院", "complexity_tier": "T3", "furigana": "そぼ いま びょういん", "sentence_source": "generated"}, {"text": "この病院は夜もあいている。", "target_word": "病院", "complexity_tier": "T3", "furigana": "びょういん よる", "sentence_source": "generated"}, {"text": "けがをした友だちを病院に運んだ。", "target_word": "病院", "complexity_tier": "T3", "furigana": "とも びょういん はこ", "sentence_source": "generated"}, {"text": "病院では静かにしてください。", "target_word": "病院", "complexity_tier": "T3", "furigana": "びょういん しず", "sentence_source": "generated"}, {"text": "母は病院で働いている。", "target_word": "病院", "complexity_tier": "T3", "furigana": "はは びょういん はたら", "sentence_source": "generated"}, {"text": "新しい病院が町にできた。", "target_word": "病院", "complexity_tier": "T3", "furigana": "あたら びょういん まち", "sentence_source": "generated"}, {"text": "病院までバスで十分かかる。", "target_word": "病院", "complexity_tier": "T3", "furigana": "びょういん じっぷん", "sentence_source": "generated"}], "morphological_forms": [{"form": "軒", "label": "助数詞"}, {"form": "大病院", "label": "派生"}, {"form": "病院食", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 病気やけがを治す所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb