INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51449, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをのせて、上へかさねる。", "primary_collocate": null, "pronunciation": "つむ", "ipa": "tsɯmɯ", "syllable_count": 2, "sentences": [{"text": "箱を三つ積む。", "target_word": "積む", "complexity_tier": "T3", "furigana": "はこ みっ つ", "sentence_source": "generated"}, {"text": "トラックに荷物を積んだ。", "target_word": "積んだ", "complexity_tier": "T3", "furigana": "にもつ つ", "sentence_source": "generated"}, {"text": "机の上に本が積んである。", "target_word": "積んで", "complexity_tier": "T3", "furigana": "つくえ うえ ほん つ", "sentence_source": "generated"}, {"text": "子どもが積み木を高く積んでいる。", "target_word": "積んで", "complexity_tier": "T3", "furigana": "こ つ き たか つ", "sentence_source": "generated"}, {"text": "積んだ皿が倒れそうだ。", "target_word": "積んだ", "complexity_tier": "T3", "furigana": "つ さら たお", "sentence_source": "generated"}, {"text": "薪を小屋の前に積む。", "target_word": "積む", "complexity_tier": "T3", "furigana": "まき こや まえ つ", "sentence_source": "generated"}, {"text": "石を積んで小さな塔を作った。", "target_word": "積んで", "complexity_tier": "T3", "furigana": "いし つ ちい とう つく", "sentence_source": "generated"}, {"text": "重い箱は下に積もう。", "target_word": "積もう", "complexity_tier": "T3", "furigana": "おも はこ した つ", "sentence_source": "generated"}, {"text": "この車にはもっと荷物が積める。", "target_word": "積める", "complexity_tier": "T3", "furigana": "くるま にもつ つ", "sentence_source": "generated"}, {"text": "雑誌を床に積むのはやめて。", "target_word": "積む", "complexity_tier": "T3", "furigana": "ざっし ゆか つ", "sentence_source": "generated"}], "morphological_forms": [{"form": "積んだ", "label": "活用"}, {"form": "積んで", "label": "活用"}, {"form": "積まない", "label": "活用"}, {"form": "積める", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 物を上に重ねてのせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'c