INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41367, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "磨く", "is_correct": true, "explanation": "みがく。聞こえた語そのもの。"}, {"text": "医学", "is_correct": false, "explanation": "いがく：最初の「み」が「い」に変わった一モーラ差。"}, {"text": "味覚", "is_correct": false, "explanation": "みかく：「が」が「か」になった清濁の違い。"}, {"text": "身軽", "is_correct": false, "explanation": "みがる：最後の「く」が「る」に変わった一モーラ差。"}, {"text": "地学", "is_correct": false, "explanation": "ちがく：最初の「み」が「ち」に変わった一モーラ差。"}], "explanations": {"磨く": "みがく。聞こえた語そのもの。", "医学": "いがく：最初の「み」が「い」に変わった一モーラ差。", "味覚": "みかく：「が」が「か」になった清濁の違い。", "身軽": "みがる：最後の「く」が「る」に変わった一モーラ差。", "地学": "ちがく：最初の「み」が「ち」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "磨く"}, "level_3": {"options": [{"text": "磨く", "is_correct": true, "explanation": "歯をきれいにすることを「歯を磨く」と言う。"}, {"text": "洗う", "is_correct": false, "explanation": "意味：歯は「洗う」とは普通言わない。"}, {"text": "切る", "is_correct": false, "explanation": "意味：毎朝歯を切ることはない。"}, {"text": "飲む", "is_correct": false, "explanation": "連語：歯を「飲む」は結びつかない。"}], "explanations": {"磨く": "歯をきれいにすることを「歯を磨く」と言う。", "洗う": "意味：歯は「洗う」とは普通言わない。", "切る": "意味：毎朝歯を切ることはない。", "飲む": "連語：歯を「飲む」は結びつかない。"}, "sentence_index": 0, "correct_answer": "磨く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の話を磨いてください。", "explanation": "話はこすってきれいにするものではない。"}, {"text": "のどがかわいたので水を磨いた。", "explanation": "水は磨くものではない。飲むが正しい。"}, {"text": "母は晩ご飯を磨いた。", "explanation": "晩ご飯は作るもので、こすってつやを出すものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_