INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41367, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「磨く」の目的語「車」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「車が磨いている」では車が動作主になり不自然。"}, {"text": "で", "is_correct": false, "explanation": "「車で磨く」は手段になり、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「磨く」の目的語「車」を示す。", "が": "「車が磨いている」では車が動作主になり不自然。", "で": "「車で磨く」は手段になり、意味が通らない。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "汚す", "is_correct": true, "explanation": "きれいにする「磨く」の反対で、よごすこと。"}, {"text": "拭く", "is_correct": false, "explanation": "きれいにする動作で、反対ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "きれいにする動作で、反対ではない。"}, {"text": "塗る", "is_correct": false, "explanation": "表面に何かをつける動作で、反対の意味ではない。"}], "correct_answer": "汚す", "explanations": {"汚す": "きれいにする「磨く」の反対で、よごすこと。", "拭く": "きれいにする動作で、反対ではない。", "洗う": "きれいにする動作で、反対ではない。", "塗る": "表面に何かをつける動作で、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
