INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41367, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母はスープを磨いてから飲んだ。", "corrected_sentence": "母はスープを温めてから飲んだ。", "error_description": "スープはこすってつやを出すものではないので「磨く」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "磨かれて", "is_correct": true, "explanation": "「よく〜ている」で受身のて形「磨かれて」。"}, {"text": "磨かせて", "is_correct": false, "explanation": "使役になり、だれに磨かせたか分からず不自然。"}, {"text": "磨いた", "is_correct": false, "explanation": "た形は「ている」につながらない。"}, {"text": "磨いて", "is_correct": false, "explanation": "能動のて形では「鏡は」が主語として合わない。"}], "correct_form": "磨かれて", "base_form": "磨く", "form_label": "受身・て形", "sentence_index": 7, "explanations": {"磨かれて": "「よく〜ている」で受身のて形「磨かれて」。", "磨かせて": "使役になり、だれに磨かせたか分からず不自然。", "磨いた": "た形は「ている」につながらない。", "磨いて": "能動のて形では「鏡は」が主語として合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
