INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42902, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家畜", "is_correct": true, "explanation": "かちく。読み上げられた語。"}, {"text": "家族", "is_correct": false, "explanation": "かぞく：「ち」が「ぞ」に変わった一モーラ差。"}, {"text": "勝気", "is_correct": false, "explanation": "かちき：「く」が「き」に変わった一モーラ差。"}, {"text": "化学", "is_correct": false, "explanation": "かがく：「ち」が「が」に変わった一モーラ差。"}, {"text": "価格", "is_correct": false, "explanation": "かかく：「ち」が「か」に変わった一モーラ差。"}], "explanations": {"家畜": "かちく。読み上げられた語。", "家族": "かぞく：「ち」が「ぞ」に変わった一モーラ差。", "勝気": "かちき：「く」が「き」に変わった一モーラ差。", "化学": "かがく：「ち」が「が」に変わった一モーラ差。", "価格": "かかく：「ち」が「か」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "家畜"}, "level_3": {"options": [{"text": "家畜", "is_correct": true, "explanation": "農場で飼う動物なので「家畜」。"}, {"text": "家具", "is_correct": false, "explanation": "意味：農場に多いのは家具ではない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：祖父の農場に宿題が多いとは言わない。"}, {"text": "電車", "is_correct": false, "explanation": "意味：農場に電車が多いとは言わない。"}], "explanations": {"家畜": "農場で飼う動物なので「家畜」。", "家具": "意味：農場に多いのは家具ではない。", "宿題": "意味：祖父の農場に宿題が多いとは言わない。", "電車": "意味：農場に電車が多いとは言わない。"}, "sentence_index": 0, "correct_answer": "家畜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上の家畜を片づけた。", "explanation": "家畜は生きた動物で、机の上に置く物ではない。"}, {"text": "家畜を本だなにならべた。", "explanation": "家畜は本だなにならべる物ではない。"}, {"text": "森の家畜が自由に暮らしている。", "explanation": "人が飼わない野生の動物は家畜ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
