INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42902, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「掃除」を「手伝った」の目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "「掃除が手伝った」では掃除が動作主になる。"}, {"text": "に", "is_correct": false, "explanation": "「掃除に手伝った」は「手伝う」の目的語にならず非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「掃除」を「手伝った」の目的語として示す。", "が": "「掃除が手伝った」では掃除が動作主になる。", "に": "「掃除に手伝った」は「手伝う」の目的語にならず非文。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51415, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手伝い", "is_correct": true, "explanation": "てつだい。読み上げられた語。"}, {"text": "末代", "is_correct": false, "explanation": "まつだい：最初の「て」が「ま」に変わった一モーラ差。"}, {"text": "絶大", "is_correct": false, "explanation": "ぜつだい：最初の「て」が「ぜ」に変わった一モーラ差。"}, {"text": "鉄材", "is_correct": false, "explanation": "てつざい：「だ」が「ざ」に変わった一モーラ差。"}], "explanations": {"手伝い": "てつだい。読み上げられた語。", "末代": "まつだい：最初の「て」が「ま」に変わった一モーラ差。", "絶大": "ぜつだい：最初の「て」が「ぜ」に変わった一モーラ差。", "鉄材": "てつざい：「だ」が「ざ」に変わった一モーラ差。"}, "sentence_index": null, "correct_answer": "手伝い"}, "level_3": {"options": [{"text": "手伝い", "is_correct": true, "explanation": "母を助けて皿を洗ったので「手伝い」。"}, {"text": "写真", "is_correct": false, "explanation": "意味：写真で皿を洗うことはない。"}, {"text": "けんか", "is_correct": false, "explanation": "意味：けんかで皿を洗うのは不自然。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：昼寝しながら皿は洗えない。"}], "explanations": {"手伝い": "母を助けて皿を洗ったので「手伝い」。", "写真": "意味：写真で皿を洗うことはない。", "けんか": "意味：けんかで皿を洗うのは不自然。", "昼寝": "意味：昼寝しながら皿は洗えない。"}, "sentence_index": 0, "correct_answer": "手伝い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は一人で全部やったので、手伝いをした。", "explanation": "一人で自分の分をすることは手伝いではない。"}, {"text": "弟は私の手伝いを食べた。", "explanation": "手伝いは食べ物ではない。"}, {"text": "弟の手伝いで、母の仕事が二倍に増えた。", "explanation": "手伝いは仕事を楽にすることで、増やすことではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51415, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちの手伝いで、ぼくの仕事は遅れた。", "corrected_sentence": "友だちの手伝いで、ぼくの仕事は早く終わった。", "error_description": "手伝いは仕事を助けるもので、遅らせるものではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51415, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「行く」の目的「手伝い」を示す。"}, {"text": "を", "is_correct": false, "explanation": "「手伝いを行く」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「手伝いが行く」では手伝いが主語になる。"}, {"text": "の", "is_correct": false, "explanation": "「手伝いの行く」は名詞が動詞を直接修飾でき非文。"}], "correct_answer": "に", "explanations": {"に": "「行く」の目的「手伝い」を示す。", "を": "「手伝いを行く」は非文。", "が": "「手伝いが行く」では手伝いが主語になる。", "の": "「手伝いの行く」は名詞が動詞を直接修飾でき非文。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "の": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "邪魔", "is_correct": true, "explanation": "手伝いと反対に、人の仕事をさまたげること。"}, {"text": "協力", "is_correct": false, "explanation": "人を助けることで、反対ではない。"}, {"text": "応援", "is_correct": false, "explanation": "人を支えることで、反対ではない。"}, {"text": "世話", "is_correct": false, "explanation": "人の面倒を見ることで、反対ではない。"}], "correct_answer": "邪魔", "explanations": {"邪魔": "手伝いと反対に、人の仕事をさまたげること。", "協力": "人を助けることで、反対ではない。", "応援": "人を支えることで、反対ではない。", "世話": "人の面倒を見ることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51415, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手伝い", "is_correct": true, "explanation": "てつだい。読み上げられた語。"}, {"text": "天台", "is_correct": false, "explanation": "てんだい：「つ」が「ん」になった一モーラ差。"}, {"text": "鉄材", "is_correct": false, "explanation": "てつざい：「だ」が「ざ」になった一モーラ差。"}, {"text": "設題", "is_correct": false, "explanation": "せつだい：最初の「て」が「せ」になった一モーラ差。"}], "explanations": {"手伝い": "てつだい。読み上げられた語。", "天台": "てんだい：「つ」が「ん」になった一モーラ差。", "鉄材": "てつざい：「だ」が「ざ」になった一モーラ差。", "設題": "せつだい：最初の「て」が「せ」になった一モーラ差。"}, "sentence_index": null, "correct_answer": "手伝い"}, "level_3": {"options": [{"text": "手伝い", "is_correct": true, "explanation": "友だちに助けてもらったので宿題が早く終わった。"}, {"text": "邪魔", "is_correct": false, "explanation": "意味：邪魔では宿題は早く終わらない。"}, {"text": "悪口", "is_correct": false, "explanation": "意味：悪口で宿題が早く終わることはない。"}, {"text": "遅刻", "is_correct": false, "explanation": "意味：遅刻で宿題が早く終わるのは不自然。"}], "explanations": {"手伝い": "友だちに助けてもらったので宿題が早く終わった。", "邪魔": "意味：邪魔では宿題は早く終わらない。", "悪口": "意味：悪口で宿題が早く終わることはない。", "遅刻": "意味：遅刻で宿題が早く終わるのは不自然。"}, "sentence_index": 6, "correct_answer": "手伝い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手伝いに来て、何もせずに帰った。", "explanation": "何もしないのは手伝いではない。"}, {"text": "手伝いを読んで、よく分かった。", "explanation": "手伝いは読むものではない。"}, {"text": "手伝いが痛くて、病院へ行った。", "explanation": "手伝いは体の部分ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '256a5d0f-4bbb-4b17-b85f-1c509b4967bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
