INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38858, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "何度も起こることの数を数えるときに使う言葉。", "primary_collocate": null, "pronunciation": "かい", "ipa": "kai", "syllable_count": 2, "sentences": [{"text": "一日に三回歯をみがく。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "この映画は二回見ました。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "何回も電話をかけた。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "週に一回、プールに行く。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "彼は三回目で合格した。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "一回だけ試してみよう。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "月に二回、祖母に会う。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "五回練習したら上手になった。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "失敗は一回では終わらない。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "その本は四回読み返した。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}], "morphological_forms": [{"form": "何回", "label": "派生"}, {"form": "毎回", "label": "派生"}, {"form": "今回", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | 起こった度数を数える言葉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: みが