INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38859, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "物事がくり返される度数を表す単位。", "primary_collocate": null, "pronunciation": "かい", "ipa": "kai", "syllable_count": 2, "sentences": [{"text": "授業は全部で十回ある。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "大会は年に一回開かれる。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "この大会は第三回だ。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "薬は一日二回飲んでください。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "次の会議は四回目です。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "一回の練習は一時間だ。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "ゲームは三回まで遊べる。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "祭りは今年で十回になる。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "発表は二回に分けて行う。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}, {"text": "この道を何回通っただろう。", "target_word": "回", "complexity_tier": "T3", "furigana": "かい", "sentence_source": "generated"}], "morphological_forms": [{"form": "回数", "label": "派生"}, {"form": "何回", "label": "派生"}, {"form": "前回", "label": "派生"}], "register": "plain", "sense_fingerprint": "接尾辞 | くり返しの度数を表す単位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2fd7d2b3-ecb8-4f5c-8cbf-e8c4da9cdbab') ON CONFLICT (sense_id, asset_typ