INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38878, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものにさわったり見たりしたときに感じる、材質の感じ。", "primary_collocate": null, "pronunciation": "しつかん", "ipa": "ɕitsɯkaɴ", "syllable_count": 4, "sentences": [{"text": "この布は質感がとてもいい。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "木の質感が好きです。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "絵で岩の質感を表した。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "質感のある紙を選んだ。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "このかばんは質感が柔らかい。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "写真では質感が伝わらない。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "彼は革の質感にこだわる。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "質感を確かめてから買う。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "壁の質感が少しざらざらだ。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}, {"text": "粘土で肌の質感を作った。", "target_word": "質感", "complexity_tier": "T3", "furigana": "しつかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感がある", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 材料から受けるさわった感じ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2fd7d2b3-ecb8-4f5c-8cbf-e8c4da9cdbab') ON CONFLICT (sense_id, asset_type) DO UPDAT