INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38926, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "会社や役所などに雇われて、そこで働く。", "primary_collocate": null, "pronunciation": "つとめる", "ipa": "tsɯtomeɾɯ", "syllable_count": 4, "sentences": [{"text": "父は銀行に勤めている。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "姉は病院に勤めています。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "彼は十年その会社に勤めた。", "target_word": "勤めた", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "市役所に勤める人が来た。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "どこに勤めているのですか。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "母は工場に勤めて長い。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "兄は東京の会社に勤めている。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "勤めている店が休みだ。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "私は書店に勤めたい。", "target_word": "勤め", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "おじは学校に勤めていた。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}], "morphological_forms": [{"form": "勤めた", "label": "活用"}, {"form": "勤めて", "label": "活用"}, {"form": "勤めない", "label": "活用"}, {"form": "勤め先", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 会社などに雇われて働く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2fd7d2b3-e