INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38927, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "与えられた仕事や務めを、まじめに一生けんめい行う。", "primary_collocate": null, "pronunciation": "つとめる", "ipa": "tsɯtomeɾɯ", "syllable_count": 4, "sentences": [{"text": "祖父は寺で朝の勤めを勤める。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "彼は毎日まじめに勤めた。", "target_word": "勤めた", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "休まずに勤める姿は立派だ。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "彼女は長年熱心に勤めてきた。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "一生けんめい勤めることが大切だ。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "最後まで誠実に勤めたい。", "target_word": "勤め", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "店でよく勤めてくれた。", "target_word": "勤めて", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "彼は黙って勤め続けた。", "target_word": "勤め", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "真面目に勤める人は信頼される。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}, {"text": "僧は毎朝お経を勤める。", "target_word": "勤める", "complexity_tier": "T3", "furigana": "つと", "sentence_source": "generated"}], "morphological_forms": [{"form": "勤めた", "label": "活用"}, {"form": "勤めて", "label": "活用"}, {"form": "勤め", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 務めをまじめに一生けんめい行う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2fd7d2b3-ecb8-4f5c-8cbf-